import random
def I(c): return .5*((c['AA']-c['AB'])+(c['BB']-c['BA']))
def y(r,a): return int(a=={'A':-1,'B':1}[r])
def cells(a): return {r+s:y(r,a[s]) for r in 'AB' for s in 'AB'}
aware={'A':-1,'B':1}; blind={'A':-1,'B':-1}
print('aware',cells(aware),I(cells(aware)))
print('blind_exact',cells(blind),I(cells(blind)),'endpoint_gap',1)
x={'A':-.01,'B':.01}; bad={s:(-1 if x[s]<0 else 1) for s in 'AB'}
print('blind_state_mismatch',bad,cells(bad),I(cells(bad)))
r=random.Random(1); seq={'A':-1 if r.random()<.5 else 1,'B':-1 if r.random()<.5 else 1}
reset={s:(-1 if random.Random(1).random()<.5 else 1) for s in 'AB'}
print('blind_sequential_rng',seq,I(cells(seq)))
print('blind_reset_rng',reset,I(cells(reset)))
carried={'AA':1,'AB':0,'BB':1,'BA':0}; fresh={'AA':1,'AB':1,'BB':0,'BA':0}
print('blind_carried_cache',I(carried),'blind_fresh_continuation',I(fresh))
print('coverage',3/4,'excluded',1)
